import math

def check_n(n):
    """
    Checks if for all k such that gcd(k, n) = 1, we have k^2 = 1 (mod n).
    """
    if n <= 1:
        return False # Problem states n >= 2

    # We only need to check k in the range 1 <= k < n
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 mod n is 1
            if (k * k) % n != 1:
                # Found a counterexample
                return False, k
    # All coprime k satisfied the condition
    return True, None

results = {}
for n in range(2, 11):
    is_solution, counter_example = check_n(n)
    results[n] = (is_solution, counter_example)

print("Results for n=2 to 10:")
for n, (is_sol, ce) in results.items():
    if is_sol:
        print(f"n={n}: YES (satisfies condition)")
    else:
        print(f"n={n}: NO (counterexample k={ce})")

