    """Checks if k^2 == 1 (mod n) for all k coprime to n."""

    # Check residues k from 1 up to n-1
    for k in range(1, n):
        if __import__('math').gcd(k, n) == 1:
            if (k * k) % n != 1:
                return False, k, (k * k) % n
    return True, None, None

